//! Regenerate the legacy metric fixture's logical rows without Python/PyArrow.
//! The historical PyArrow binary stays pinned independently; Parquet bytes
//! generated by Arrow Rust are not expected to be byte-identical to it.
use arrow::array::{ArrayRef, BinaryArray, Float64Array, Int64Array, RecordBatch, StringArray};
use arrow::datatypes::{DataType, Field, Schema};
use parquet::arrow::ArrowWriter;
use parquet::basic::{Compression, ZstdLevel};
use parquet::file::properties::WriterProperties;
use std::{fs::File, sync::Arc};

fn main() {
    let output = std::env::args().nth(1).expect("output parquet path");
    let fields = vec![
        Field::new("series_id", DataType::Int64, false),
        Field::new("timestamp_ns", DataType::Int64, false),
        Field::new("value", DataType::Float64, false),
        Field::new("metric_name", DataType::Utf8, false),
        Field::new("labels_canonical", DataType::Binary, false),
        Field::new("labels_json", DataType::Utf8, false),
    ];
    let columns: Vec<ArrayRef> = vec![
        Arc::new(Int64Array::from(vec![1, 2])),
        Arc::new(Int64Array::from(vec![1, 2])),
        Arc::new(Float64Array::from(vec![
            1.0,
            f64::from_bits(0x7FF0000000000002),
        ])),
        Arc::new(StringArray::from(vec!["safe", "unsafe"])),
        Arc::new(BinaryArray::from(vec![
            b"__name__\xffsafe\xff".as_slice(),
            b"__name__\xffunsafe\xff".as_slice(),
        ])),
        Arc::new(StringArray::from(vec![
            r#"{"__name__":"safe"}"#,
            r#"{"__name__":"unsafe"}"#,
        ])),
    ];
    let batch = RecordBatch::try_new(Arc::new(Schema::new(fields)), columns).unwrap();
    let properties = WriterProperties::builder()
        .set_compression(Compression::ZSTD(ZstdLevel::default()))
        .build();
    let mut writer = ArrowWriter::try_new(
        File::create(output).unwrap(),
        batch.schema(),
        Some(properties),
    )
    .unwrap();
    writer.write(&batch).unwrap();
    writer.close().unwrap();
}
